<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title??env('APP_NAME'))?></title><link rel="stylesheet" href="<?=e(url('/css/style.css'))?>"><style>body{margin:0;font-family:Arial,sans-serif;background:#f5f7fb}.top{display:flex;justify-content:space-between;align-items:center;padding:14px 24px;background:#fff;border-bottom:1px solid #ddd}.wrap{padding:24px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:16px}.card{background:#fff;padding:20px;border-radius:12px;box-shadow:0 2px 10px #00000010}.logout{border:0;background:none;cursor:pointer;font:inherit;color:var(--red-fg,#b91c1c);font-weight:600;padding:6px 10px;border-radius:6px}.logout:hover{background:#fef2f2}@media(max-width:640px){.top{padding:12px 16px}.wrap{padding:16px}}</style><script src="<?=e(url('/js/accessibility.js'))?>"></script></head><body><a class="skip-link" href="#main-content">Skip to main content</a><header class="top"><strong><?=e(env('APP_NAME','IMS'))?></strong><form method="post" action="<?=e(url('/logout'))?>"><?=csrf_field()?><button type="submit" class="logout">Logout</button></form></header><main class="wrap" id="main-content" tabindex="-1"><?=$content?></main></body></html>